// Builds the alert email (spec §10 WF09). Sends nothing if no recipient is configured yet.
const err = $('On workflow error').first().json;
const to = ($input.first()?.json?.value || '').trim();
if (!to) return [];
const wf = err.workflow?.name || 'unknown workflow';
const exec = err.execution || {};
const lines = [
  `Workflow: ${wf}`,
  `Node: ${exec.lastNodeExecuted || 'unknown'}`,
  `Error: ${exec.error?.message || 'unknown error'}`,
  `Execution: ${exec.url || exec.id || 'n/a'}`,
  `Mode: ${exec.mode || 'n/a'}`,
];
return [{ json: { to, subject: `[Leftover] ${wf} failed`, body: lines.join('\n') } }];
